package com.company.platform.administration.domain;import java.time.Instant;import java.util.*;public record Tenant(UUID id,String code,String name,String status,String plan,String configuration,Instant createdAt,Instant updatedAt){public Tenant{if(id==null||code==null||code.isBlank()||name==null||name.isBlank()||status==null||plan==null||configuration==null||createdAt==null||updatedAt==null)throw new IllegalArgumentException("invalid tenant");}public static Tenant create(String c,String n,String p,String cfg){Instant now=Instant.now();return new Tenant(UUID.randomUUID(),c,n,"ACTIVE",p,cfg,now,now);}public Tenant suspend(){return new Tenant(id,code,name,"SUSPENDED",plan,configuration,createdAt,Instant.now());}public Tenant activate(){return new Tenant(id,code,name,"ACTIVE",plan,configuration,createdAt,Instant.now());}}
